def load() -> pd.DataFrame:
    import glob
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201810??T235942_201810??T235942_0201/*.sp3'))
    lines = []
    with open(files[0], 'r') as f:
        for i, line in enumerate(f):
            if i >= 40:
                break
            lines.append({'line_no': i, 'content': line.rstrip()})
    return pd.DataFrame(lines)
